INSERT OR IGNORE INTO doctors (id, slug, name, gender, patients_treated, qualifications, registration_number, registration_council, is_verified, verified_at, experience_years, languages, bio, video_consult, video_fee, phone, whatsapp, website, google_maps_url, rating_avg, review_count, recommend_pct, is_published, source) VALUES
 ('doc_arjun_mehta','dr-arjun-mehta','Dr. Arjun Mehta','male','men','["MBBS","MD (Psychiatry)"]','DMC/R/SAMPLE-001','Delhi Medical Council',1,datetime('now'),14,'["Hindi","English","Punjabi"]','Dr. Arjun Mehta is a Delhi-based sexologist with a background in psychiatry. He treats erectile dysfunction, premature ejaculation, performance anxiety and low desire, and works with couples on intimacy concerns. He combines medical treatment with counselling and coordinates with urologists when further tests are needed.',1,600,'+919811000001','+919811000001','https://example.com/saket-wellness','https://maps.google.com/?q=28.5262,77.2089',4.8,3,96,1,'manual'),
 ('doc_vikram_sethi','dr-vikram-sethi','Dr. Vikram Sethi','male','men','["MBBS","MS","DNB (Urology)"]','DMC/R/SAMPLE-002','Delhi Medical Council',1,datetime('now'),18,'["Hindi","English","Punjabi"]','Dr. Vikram Sethi is a urologist with special interest in erectile dysfunction, Peyronie''s disease and prostate-related sexual problems.',1,700,'+919811000003','+919811000003','https://example.com/dwarka-uro','https://maps.google.com/?q=28.5950,77.0490',4.6,3,91,1,'manual'),
 ('doc_meera_kapoor','dr-meera-kapoor','Dr. Meera Kapoor','female','women','["MBBS","MD (OBG)"]','DMC/R/SAMPLE-003','Delhi Medical Council',1,datetime('now'),15,'["Hindi","English"]','Dr. Meera Kapoor is a gynaecologist focusing on menopause, vaginal dryness and painful intercourse, with a practical, hormone-aware approach.',1,700,'+919811000004','+919811000004',NULL,'https://maps.google.com/?q=28.5660,77.2455',4.8,3,97,1,'manual'),
 ('doc_farhan_siddiqui','dr-farhan-siddiqui','Dr. Farhan Siddiqui','male','both','["MBBS","MD"]','DMC/R/SAMPLE-004','Delhi Medical Council',1,datetime('now'),16,'["Hindi","Urdu","English"]','Dr. Farhan Siddiqui is a sexologist and couples therapist. He works with individuals and couples on premature ejaculation, desire mismatch, STI anxiety and communication about sex.',1,900,'+919811000005','+919811000005',NULL,'https://maps.google.com/?q=28.6530,77.1920',4.7,3,94,1,'manual'),
 ('doc_priya_deshmukh','dr-priya-deshmukh','Dr. Priya Deshmukh','female','both','["MBBS","MD (Dermatology, Venereology & Leprosy)"]','DMC/R/SAMPLE-005','Delhi Medical Council',1,datetime('now'),11,'["Marathi","Hindi","English"]','Dr. Priya Deshmukh is a venereologist who diagnoses and treats sexually transmitted infections, genital skin conditions and offers confidential STI testing.',1,600,'+919811000006','+919811000006',NULL,'https://maps.google.com/?q=28.7480,77.0590',4.8,2,95,1,'manual'),
 ('doc_imran_qureshi','dr-imran-qureshi','Dr. Imran Qureshi','male','men','["MBBS","MD (Medicine)"]','DMC/R/SAMPLE-006','Delhi Medical Council',1,datetime('now'),20,'["Urdu","Hindi","English"]','Dr. Imran Qureshi is a physician and sexologist with two decades of experience managing diabetes-related erectile problems and low desire.',1,500,'+919811000007','+919811000007',NULL,'https://maps.google.com/?q=28.6230,77.0890',4.6,3,90,1,'manual'),
 ('doc_neha_agarwal','dr-neha-agarwal','Dr. Neha Agarwal','female','women','["MBBS","MS (OBG)"]','DMC/R/SAMPLE-007','Delhi Medical Council',1,datetime('now'),10,'["Hindi","English"]','Dr. Neha Agarwal is a gynaecologist focusing on fertility, PCOS and sexual health for couples trying to conceive.',1,500,'+919811000008','+919811000008','https://example.com/gk-fertility','https://maps.google.com/?q=28.5500,77.2380',4.8,2,96,1,'manual'),
 ('doc_aditya_rao','dr-aditya-rao','Dr. Aditya Rao','male','men','["MBBS","MD (Psychiatry)","Diploma in Sexual Medicine"]','KMC/SAMPLE-001','Karnataka Medical Council',1,datetime('now'),8,'["Kannada","Hindi","English","Telugu"]','Dr. Aditya Rao is a sexologist treating performance anxiety, premature ejaculation and erectile problems in younger men, with evidence-based behavioural therapy.',1,600,'+919845000001','+919845000001',NULL,'https://maps.google.com/?q=12.9345,77.6250',4.7,3,93,1,'manual'),
 ('doc_lakshmi_nair','dr-lakshmi-nair','Dr. Lakshmi Nair','female','women','["MBBS","DNB (OBG)"]','KMC/SAMPLE-002','Karnataka Medical Council',1,datetime('now'),13,'["Malayalam","Kannada","English"]','Dr. Lakshmi Nair treats vaginismus, orgasm concerns and PCOS-related sexual health, working with physiotherapists and counsellors.',1,700,'+919845000002','+919845000002',NULL,'https://maps.google.com/?q=12.9790,77.6400',4.9,3,98,1,'manual'),
 ('doc_kavya_iyer','dr-kavya-iyer','Dr. Kavya Iyer','female','women','["MBBS","MS (OBG)","Fellowship in Sexual Medicine"]','KMC/SAMPLE-003','Karnataka Medical Council',1,datetime('now'),12,'["Tamil","Hindi","English","Kannada"]','Dr. Kavya Iyer is a gynaecologist with a fellowship in sexual medicine. She treats low desire, painful sex, vaginismus and menopause-related concerns, and offers pelvic floor and couples-based therapy alongside medical treatment.',1,700,'+919845000003','+919845000003',NULL,'https://maps.google.com/?q=12.9260,77.5930',4.9,3,98,1,'manual'),
 ('doc_karthik_subramanian','dr-karthik-subramanian','Dr. Karthik Subramanian','male','men','["MBBS","MS","MCh (Urology)"]','KMC/SAMPLE-004','Karnataka Medical Council',1,datetime('now'),12,'["Tamil","English","Kannada"]','Dr. Karthik Subramanian is an andrologist managing male infertility, varicocele and erectile dysfunction.',1,600,'+919845000004','+919845000004',NULL,'https://maps.google.com/?q=12.9120,77.6400',4.7,2,92,1,'manual'),
 ('doc_sneha_reddy','dr-sneha-reddy','Dr. Sneha Reddy','female','both','["MBBS","MD (Psychiatry)"]','KMC/SAMPLE-005','Karnataka Medical Council',1,datetime('now'),10,'["Telugu","Hindi","English","Kannada"]','Dr. Sneha Reddy is a psychiatrist specialising in sexual and relationship health, including menopause-related intimacy changes, sexual anxiety and couples counselling.',1,600,'+919845000005','+919845000005',NULL,'https://maps.google.com/?q=12.9700,77.7490',4.9,3,97,1,'manual'),
 ('doc_rohan_kulkarni','dr-rohan-kulkarni','Dr. Rohan Kulkarni','male','men','["MBBS","MS","MCh (Urology)"]','MPMC/SAMPLE-001','Madhya Pradesh Medical Council',1,datetime('now'),11,'["Marathi","Hindi","English"]','Dr. Rohan Kulkarni is a urologist and andrologist. He manages erectile dysfunction, low testosterone, male infertility and Peyronie''s disease, including Doppler studies and surgical options when needed.',1,800,'+919826000001','+919826000001',NULL,'https://maps.google.com/?q=22.7540,75.8930',4.7,3,93,1,'manual'),
 ('doc_ananya_banerjee','dr-ananya-banerjee','Dr. Ananya Banerjee','female','women','["MBBS","DGO"]','MPMC/SAMPLE-002','Madhya Pradesh Medical Council',1,datetime('now'),9,'["Bengali","Hindi","English"]','Dr. Ananya Banerjee is a gynaecologist and sexologist who focuses on painful sex after childbirth, low desire and contraception counselling.',1,500,'+919826000002','+919826000002',NULL,'https://maps.google.com/?q=22.7250,75.8830',4.8,2,95,1,'manual');

